/bin/zsh -lc "python3 - <<'PY'
import json, hashlib
from pathlib import Path
from datetime import datetime
for name in ('regras.md', 'eventos.json'):
    print(name, hashlib.sha256(Path(name).read_bytes()).hexdigest())
raw = json.loads(Path('eventos.json').read_text())
unique = {}
duplicates = []
for event in raw:
    key = event['event_id']
    if key in unique:
        assert unique[key] == event, f'Duplicata conflitante: {key}'
        duplicates.append(key)
    else:
        unique[key] = event
start = datetime.fromisoformat('2026-10-10T00:00:00+00:00')
end = datetime.fromisoformat('2026-10-11T00:00:00+00:00')
def instant(event):
    return datetime.fromisoformat(event['em'].replace('Z', '+00:00'))
payments = [e for e in unique.values() if e['tipo'] == 'pago' and e['moeda'] == 'BRL' and start <= instant(e) < end]
channels = {'loja': 0, 'web': 0}
rows = []
for payment in sorted(payments, key=lambda e:e['pedido']):
    refunds = [e for e in unique.values() if e['pedido'] == payment['pedido'] and e['tipo'] == 'estorno_confirmado' and instant(e) < end]
    net = payment['valor'] - sum(e['valor'] for e in refunds)
    channels[payment['canal']] += net
    rows.append({'pedido': payment['pedido'], 'pagamento': payment['event_id'], 'bruto': payment['valor'], 'estornos': [e['event_id'] for e in refunds], 'liquido': net, 'canal': payment['canal']})
print(json.dumps({'registros': len(raw), 'eventos_unicos': len(unique), 'duplicatas': duplicates, 'pedidos': rows, 'por_canal': channels, 'total': sum(channels.values())}, indent=2, ensure_ascii=False))
PY"

